var Rx = [[/Downshift delay/g, "venter f\xF8r nedgang"], [/Boost hold/g, "holder boost"], [/Hysteresis/g, "hysterese"], [/RH\/CO2 normal/g, "fugt og CO\u2082 normal"], [/HA offline/g, "HA offline"], [/\(auto\)|\(low\)|\(normal\)|\(high\)|\(critical\)/g, ""]];
