  if (e === "hcp4") return { title: "HCP4-panelet styrer", level: null, reason: "Pi'en venter og skriver ikke til anl\xE6gget, s\xE5 l\xE6nge HCP4 er aktivt p\xE5 bussen.", footer: o, tone: "paused" };
