init_chart_hover();
var VERSION24 = "2.6.3";
var TAG2 = "ha-radiator-overview-card-v2";
var DASH2 = "\u2014";
var DIAL = { cx: 60, cy: 60, r: 47, start: 150, sweep: 240 };
var SPARK_W = 240;
var SPARK_H = 44;
var hasAir = (room) => [room?.co2, room?.pm25, room?.air_quality].some((id) => typeof id === "string" && id.includes("."));
