      if (/^binary_sensor\..*_(glass_break|siren)_detected$/.test(id)) result.push({ entity: id, title: `Sikkerhedsh\xE6ndelse: ${this._name(id)}`, detail: "Muligt glasbrud eller aktiv sirene", icon: "mdi:shield-alert" });
