  _miniSlider(entity, label, unit) {
    const state = this._state(entity), min = state?.attributes?.min ?? 0, max = state?.attributes?.max ?? 180, step = state?.attributes?.step ?? 1;
    return `<div class="mini-control"><span>${label}<b data-output="${this._esc(entity)}">\u2014</b></span><input type="range" min="${min}" max="${max}" step="${step}" data-range="${this._esc(entity)}"><small>${unit}</small></div>`;
  }
  _bind() {
    const root = this.shadowRoot;
    root.querySelectorAll("[data-tab]").forEach((button) => button.addEventListener("click", () => {
      this._activeRoom = Number(button.dataset.tab);
      root.querySelectorAll("[data-tab]").forEach((node) => node.classList.toggle("active", node === button));
      root.querySelectorAll("[data-room]").forEach((node) => node.classList.toggle("active", Number(node.dataset.room) === this._activeRoom));
    }));
    root.querySelectorAll("[data-toggle]").forEach((button) => button.addEventListener("click", () => this._toggle(button.dataset.toggle)));
    root.querySelectorAll("[data-info]").forEach((button) => button.addEventListener("click", () => this._moreInfo(button.dataset.info)));
    root.querySelectorAll("[data-range]").forEach((input) => {
      input.addEventListener("input", () => {
        const output = root.querySelector(`[data-output="${CSS.escape(input.dataset.range)}"]`);
        if (output) output.textContent = input.value;
      });
      input.addEventListener("change", () => this._set(input.dataset.range, input.value));
    });
    root.querySelectorAll("[data-time]").forEach((input) => input.addEventListener("change", () => this._set(input.dataset.time, input.value)));
    root.querySelector("[data-select]")?.addEventListener("change", (event) => this._set(event.target.dataset.select, event.target.value));
  }
  _sync() {
    if (!this._hass || !this.shadowRoot?.querySelector("ha-card")) return;
    const root = this.shadowRoot, d = this._config.daylight || {}, dayOn = this._on(d.active_entity);
    root.querySelector(".day-status")?.classList.toggle("on", dayOn);
    root.querySelector("[data-day-state]") && (root.querySelector("[data-day-state]").textContent = dayOn ? "Aktiv lige nu" : "Inaktiv lige nu");
    root.querySelector("[data-day-summary]") && (root.querySelector("[data-day-summary]").textContent = dayOn ? "Aktivt" : "Inaktivt");
    root.querySelectorAll("[data-value]").forEach((node) => node.textContent = this._value(node.dataset.value, "\u2014").slice(0, 5));
    const select = root.querySelector("[data-select]"), options = this._options(d.mode_entity), signature = options.join("|");
    if (select && select.dataset.options !== signature) {
      select.innerHTML = options.map((option) => `<option value="${this._esc(option)}">${this._esc(option)}</option>`).join("");
      select.dataset.options = signature;
    }
    if (select) select.value = this._value(d.mode_entity);
    root.querySelectorAll("[data-time]").forEach((input) => {
      if (root.activeElement !== input) input.value = this._value(input.dataset.time, "00:00:00").slice(0, 5);
    });
    root.querySelectorAll("[data-range]").forEach((input) => {
      const state = this._state(input.dataset.range);
      if (state) {
        input.min = state.attributes?.min ?? input.min;
        input.max = state.attributes?.max ?? input.max;
        input.step = state.attributes?.step ?? input.step;
        if (root.activeElement !== input) input.value = state.state;
      }
      const output = root.querySelector(`[data-output="${CSS.escape(input.dataset.range)}"]`);
      if (output) output.textContent = input.value;
    });
    let luxActive = 0;
    root.querySelectorAll(".switch-card[data-toggle]").forEach((button) => {
      const on = this._on(button.dataset.toggle);
      button.classList.toggle("on", on);
      button.querySelector("[data-switch-state]").textContent = on ? "Aktiv" : "Fra";
    });
    this._config.rooms.forEach((room) => {
      if (this._on(room.lux_enabled_entity)) luxActive++;
    });
    root.querySelector("[data-room-summary]").textContent = `${luxActive}/${this._config.rooms.filter((room) => room.lux_enabled_entity).length}`;
  }
  getCardSize() {
    return 7;
  }
