    const callouts = Object.keys(ANCHORS).filter((id) => this._configured(id)).map((id) => `<g data-callout="${id}" data-tone="${METRICS[id].tone}"><path/><circle class="cf-callout-ring" r="5.5"/><circle class="cf-callout-dot" r="2.2"/></g>`).join("");
